\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u0438 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b\n\n**\u0412\u043e\u043f\u0440\u043e\u0441.** \u0423\u043b\u0443\u0447\u0448\u0430\u0435\u0442 \u043b\u0438 \u0432\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u043d\u0438\u0435 chemical feedback-\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430 (p-logP, QED, binding affinity) \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044e \u043c\u043e\u043b\u0435\u043a\u0443\u043b: (H1) \u043f\u043e\u0432\u044b\u0448\u0430\u0435\u0442 property scores; (H2) \u0441\u043d\u0438\u0436\u0430\u0435\u0442 \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044f\u0440\u043d\u044b\u0435 \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0438; (H3) \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0435 \u0440\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u0435 \u0438 \u043d\u0435 \u0432\u044b\u0437\u044b\u0432\u0430\u0435\u0442 \u043f\u0435\u0440\u0435\u043a\u043e\u0441\u0430 \u043a \u0441\u0432\u0435\u0440\u0445\u0434\u043b\u0438\u043d\u043d\u044b\u043c \u0443\u0433\u043b\u0435\u0440\u043e\u0434\u043d\u044b\u043c \u0446\u0435\u043f\u044f\u043c; (H4) \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0430\u0435\u0442 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u043a real-world drug-like \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044e.\n\n\u041a\u0430\u0436\u0434\u0430\u044f \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430 \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c\u044b\u0439 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0441\u043e \u0441\u0432\u043e\u0435\u0439 \u043c\u0435\u0442\u0440\u0438\u043a\u043e\u0439; \u0432\u044b\u0432\u043e\u0434 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e \u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u043e\u0441\u0442\u0438, \u0430 \u043d\u0435 \u043f\u043e \u043e\u0434\u043d\u043e\u0439 \u0441\u0432\u043e\u0434\u043d\u043e\u0439 \u043c\u0435\u0442\u0440\u0438\u043a\u0435 (\u044f\u0432\u043d\u043e \u043e\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u043e: \u00ab\u0441\u0442\u0440\u0435\u043b\u043a\u0430 \u0432\u0432\u0435\u0440\u0445\u00bb \u043f\u043e \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430\u043c \u043f\u0440\u0438 \u043f\u0430\u0434\u0435\u043d\u0438\u0438 \u0440\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u044f \u2014 \u044d\u0442\u043e \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u0430).\n\n---\n\n## 2. \u041e\u0431\u0449\u0438\u0439 \u0434\u0438\u0437\u0430\u0439\u043d: \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u043c\u043e\u0435 A/B-\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 (+ \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u0430\u044f \u0430\u0431\u043b\u044f\u0446\u0438\u044f)\n\n| \u041f\u043b\u0435\u0447\u043e | \u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 |\n|---|---|\n| **A (baseline)** | \u0422\u0430 \u0436\u0435 \u0431\u0430\u0437\u043e\u0432\u0430\u044f \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u0441\u0438\u0441\u0442\u0435\u043c\u0430, \u0431\u0435\u0437 \u0444\u0438\u0434\u0431\u044d\u043a\u0430. \u041e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 conditioning-\u0443\u0441\u043b\u043e\u0432\u0438\u0435 (\u043e\u0434\u0438\u043d \u0442\u0430\u0440\u0433\u0435\u0442, \u043e\u0434\u0438\u043d \u043f\u0440\u043e\u043c\u043f\u0442/latent), \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u00ab\u0432 \u043e\u0434\u0438\u043d \u043f\u0440\u043e\u0445\u043e\u0434\u00bb. |\n| **B (treatment)** | \u0422\u0430 \u0436\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u0430 + chemical feedback-\u043f\u0435\u0442\u043b\u044f: \u043f\u043e\u0441\u043b\u0435 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0440\u0430\u0443\u043d\u0434\u0430 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438 \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u044e\u0442\u0441\u044f p-logP (Crippen), QED, affinity-\u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442; \u0441\u0438\u0433\u043d\u0430\u043b \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u0447\u0435\u0440\u0435\u0437 reranking / iterative refinement / conditioning (\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c-\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u043d\u043e \u2014 \u0441\u043c. \u00a74). |\n| **C, D (\u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435, \u043d\u0435 \u044f\u0434\u0440\u043e)** | \u0410\u0431\u043b\u044f\u0446\u0438\u0438: C = feedback \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e p-logP+QED; D = feedback p-logP+QED+affinity (\u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442 B). \u041f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0430\u0442\u0440\u0438\u0431\u0443\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u043a\u043b\u0430\u0434 affinity-\u043a\u0430\u043d\u0430\u043b\u0430. |\n\n**\u041a\u043b\u044e\u0447\u0435\u0432\u044b\u0435 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044b:**\n- **\u0420\u0430\u0432\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442:** \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0441\u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432 \u043d\u0430 \u043f\u043b\u0435\u0447\u043e (\u00a78), \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439 \u043f\u0435\u0442\u043b\u0438, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u2014 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u043e\u0431\u044a\u044f\u0441\u043d\u0435\u043d\u0438\u0435 \u0432\u044b\u0438\u0433\u0440\u044b\u0448\u0430 \u00ab\u0431\u043e\u043b\u044c\u0448\u0435\u0439 \u0432\u044b\u0431\u043e\u0440\u043a\u043e\u0439\u00bb.\n- **\u041e\u0431\u0449\u0438\u0435 seeds \u0438 \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u044b\u0439 \u043f\u0443\u043b:** \u043e\u0431\u0430 \u043f\u043b\u0435\u0447\u0430 \u0441\u0442\u0430\u0440\u0442\u0443\u044e\u0442 \u0438\u0437 \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u043e\u0433\u043e \u043d\u0430\u0431\u043e\u0440\u0430 seeds/\u043f\u0440\u043e\u043c\u043f\u0442\u043e\u0432; \u0433\u0434\u0435 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u2014 paired-\u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 (\u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442 A vs \u0435\u0433\u043e feedback-\u043c\u043e\u0434\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u043e\u0433 \u0438\u0437 \u0442\u043e\u0439 \u0436\u0435 seed-\u0446\u0435\u043f\u043e\u0447\u043a\u0438).\n- **\u0418\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u044b\u0439 \u043f\u0430\u0439\u043f\u043b\u0430\u0439\u043d \u043e\u0446\u0435\u043d\u043a\u0438:** \u043e\u0434\u043d\u0430 \u0432\u0435\u0440\u0441\u0438\u044f RDKit, \u043e\u0434\u0438\u043d \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442, \u043e\u0434\u0438\u043d docking-\u0431\u0438\u043d\u0430\u0440\u043d\u0438\u043a; \u043e\u0446\u0435\u043d\u043a\u0430 \u0441\u043b\u0435\u043f\u0430\u044f (\u0441\u043a\u043e\u0440\u0435\u0440 \u043d\u0435 \u0437\u043d\u0430\u0435\u0442 \u043f\u043b\u0435\u0447\u043e), \u0432\u0441\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u043e\u0434\u043d\u0438\u043c \u0441\u043a\u0440\u0438\u043f\u0442\u043e\u043c \u043f\u043e \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u043c SMILES.\n- **Dedup-\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u0437\u0430\u0440\u0430\u043d\u0435\u0435:** \u0434\u0435\u0434\u0443\u043f\u043b\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e canonical SMILES \u0434\u043e \u0440\u0430\u0441\u0447\u0451\u0442\u0430 diversity-\u043c\u0435\u0442\u0440\u0438\u043a; \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0447\u0451\u0442 \u0434\u043e\u043b\u0438 \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 (\u00a75.3) \u2014 \u0447\u0442\u043e\u0431\u044b \u043f\u0435\u0442\u043b\u044f, \u00ab\u0432\u044b\u0438\u0433\u0440\u044b\u0432\u0430\u044e\u0449\u0430\u044f\u00bb \u043a\u043e\u043b\u043b\u0430\u043f\u0441\u043e\u043c \u043a \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u043c \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430\u043c, \u0431\u044b\u043b\u0430 \u043f\u043e\u0439\u043c\u0430\u043d\u0430.\n\n---\n\n## 3. \u0412\u044b\u0431\u043e\u0440 \u0442\u0430\u0440\u0433\u0435\u0442\u0430 (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u21161)\n\n**\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 (\u0437\u0430\u0440\u0430\u043d\u0435\u0435, \u0434\u043e \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438):**\n1. \u041f\u0443\u0431\u043b\u0438\u0447\u043d\u0430\u044f \u0432\u044b\u0441\u043e\u043a\u043e\u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 (PDB, \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u2264 2.5 \u00c5, \u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u043a\u0430\u0440\u043c\u0430\u043d, \u043a\u0440\u0438\u0441\u0442\u0430\u043b\u043b\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043b\u0438\u0433\u0430\u043d\u0434 \u0434\u043b\u044f \u043a\u0440\u043e\u0441\u0441-\u0434\u043e\u043a\u0438\u043d\u0433\u0430).\n2. \u0414\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0445 \u043b\u0438\u0433\u0430\u043d\u0434\u043e\u0432 \u0432 ChEMBL (\u2265 1000 \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0439 \u0441 IC50/Ki, \u2265 200 \u00abactives\u00bb \u043f\u0440\u0438 \u043f\u043e\u0440\u043e\u0433\u0435 100 nM) \u2014 \u0434\u043b\u044f \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0438 affinity-\u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 \u0438 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u0435\u0439.\n3. \u041a\u043b\u0430\u0441\u0441 \u2014 kinase; \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u043c\u044b\u0439 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442: **EGFR** (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, PDB 1M17), \u0437\u0430\u043f\u0430\u0441\u043d\u043e\u0439 \u2014 JAK2 \u0438\u043b\u0438 ALK. \u041a\u0438\u043d\u0430\u0437\u044b \u2014 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0439 \u0431\u0435\u043d\u0447\u043c\u0430\u0440\u043a de novo design: drug-like \u043a\u0430\u0440\u043c\u0430\u043d, \u0431\u043e\u0433\u0430\u0442\u044b\u0435 ChEMBL-\u0434\u0430\u043d\u043d\u044b\u0435.\n4. \u041a\u043e\u043c\u043f\u0430\u043a\u0442\u043d\u044b\u0439/\u0436\u0451\u0441\u0442\u043a\u0438\u0439 \u043a\u0430\u0440\u043c\u0430\u043d, \u043f\u0440\u0438\u0433\u043e\u0434\u043d\u044b\u0439 \u0434\u043b\u044f fast docking (\u0438\u0441\u043a\u043b\u044e\u0447\u0430\u0435\u043c \u0433\u0438\u0431\u043a\u0438\u0435 \u0430\u043b\u043b\u043e\u0441\u0442\u0435\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0438 \u0431\u0435\u043b\u043e\u043a\u2013\u0431\u0435\u043b\u043e\u043a \u0438\u043d\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u044b).\n\n**\u0412\u043b\u0438\u044f\u043d\u0438\u0435 \u043d\u0430 \u043e\u0431\u043e\u0431\u0449\u0430\u0435\u043c\u043e\u0441\u0442\u044c (\u044f\u0432\u043d\u043e \u0432 \u043e\u0442\u0447\u0451\u0442):** \u0432\u044b\u0432\u043e\u0434 \u0441\u0442\u0440\u043e\u0438\u0442\u0441\u044f \u0434\u043b\u044f \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0430\u0440\u0433\u0435\u0442\u0430 \u043e\u0434\u043d\u043e\u0433\u043e \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430; \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u00abfeedback \u0443\u043b\u0443\u0447\u0448\u0430\u0435\u0442 targeted generation\u00bb \u0432\u0430\u043b\u0438\u0434\u0438\u0440\u0443\u0435\u0442\u0441\u044f *\u0432 \u044d\u0442\u043e\u043c \u0441\u0435\u0442\u0430\u043f\u0435*. \u041f\u0435\u0440\u0435\u043d\u043e\u0441 \u043d\u0430 \u0434\u0440\u0443\u0433\u0438\u0435 \u043a\u043b\u0430\u0441\u0441\u044b \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442. \u0427\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0435 \u0441\u043c\u044f\u0433\u0447\u0435\u043d\u0438\u0435: hold-out-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 \u043d\u0430 \u0432\u0442\u043e\u0440\u043e\u043c kinase-\u0442\u0430\u0440\u0433\u0435\u0442\u0435 \u043a\u0430\u043a sensitivity-\u0430\u043d\u0430\u043b\u0438\u0437 (\u043d\u0435 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0432\u044b\u0432\u043e\u0434).\n\n---\n\n## 4. Feedback-\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u21162, method-agnostic assumption)\n\n**Assumption (\u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e):** \u043f\u043e\u0434 \u00abchemical feedback mechanism\u00bb \u043f\u043e\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f *\u043b\u044e\u0431\u0430\u044f* \u043f\u0435\u0442\u043b\u044f, \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0449\u0430\u044f \u0432 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044e \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u043d\u044b\u0435 p-logP, QED \u0438 binding affinity \u2014 \u0447\u0435\u0440\u0435\u0437 conditioning \u043d\u0430 \u0432\u0435\u043a\u0442\u043e\u0440 \u0441\u0432\u043e\u0439\u0441\u0442\u0432, post-hoc reranking, iterative refinement \u0438\u043b\u0438 \u043a\u043e\u043c\u0431\u0438\u043d\u0430\u0446\u0438\u044e. \u0412\u044b\u0432\u043e\u0434 \u043d\u0435 \u043f\u0440\u0438\u0432\u044f\u0437\u0430\u043d \u043a \u043e\u0434\u043d\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0435. \u0424\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b: (i) \u0432 \u043f\u0435\u0442\u043b\u044e \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0442\u0441\u044f \u0432\u0441\u0435 \u0442\u0440\u0438 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430; (ii) \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439 \u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 policy \u0432\u044b\u0431\u043e\u0440\u0430 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432 (\u0437\u0430\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b); (iii) baseline \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0442\u0443 \u0436\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u0443 \u0441 \u043f\u0435\u0442\u043b\u0451\u0439, \u00ab\u043e\u0431\u043e\u0440\u0432\u0430\u043d\u043d\u043e\u0439\u00bb \u0434\u043e \u043d\u0443\u043b\u044f \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439.\n\n**\u0410\u0434\u0430\u043f\u0442\u0430\u0446\u0438\u044f \u043f\u043e\u0434 \u043a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u044b\u0439 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043c\u0435\u0442\u043e\u0434 (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e, \u043d\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435):** \u0435\u0441\u043b\u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0437\u0430\u0434\u0430\u043d, \u044f\u0434\u0440\u043e A/B \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f; \u0437\u0430\u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f \u0441\u043f\u043e\u0441\u043e\u0431 \u0438\u043d\u044a\u0435\u043a\u0446\u0438\u0438 \u0441\u0438\u0433\u043d\u0430\u043b\u0430, \u0447\u0438\u0441\u043b\u043e \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439 \u043f\u043e \u043c\u0435\u0442\u043e\u0434\u0441\u043a\u043e\u043c\u0443 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0443; \u0435\u0441\u043b\u0438 \u043c\u0435\u0442\u043e\u0434 \u0438\u043c\u0435\u0435\u0442 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 affinity-\u043c\u043e\u0434\u0443\u043b\u044c \u2014 \u043e\u043d \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043d\u0430\u0448\u0438\u043c \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u043c \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u043e\u043c, \u0447\u0442\u043e\u0431\u044b \u043e\u0431\u0430 \u043f\u043b\u0435\u0447\u0430 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u043b\u0438\u0441\u044c \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u043e (\u0438\u043d\u0430\u0447\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0438\u0442\u0441\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u043e\u043c).\n\n---\n\n## 5. \u041c\u0435\u0442\u0440\u0438\u043a\u0438\n\n### 5.1 \u0421\u0432\u043e\u0439\u0441\u0442\u0432\u0430 (H1)\n- \u0420\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f (\u0433\u0438\u0441\u0442\u043e\u0433\u0440\u0430\u043c\u043c\u044b + \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u0438, \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0440\u0435\u0434\u043d\u0438\u0435): p-logP, QED, \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u043d\u0430\u044f affinity (pIC50-\u0448\u043a\u0430\u043b\u0430 \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430).\n- **Primary property metric:** \u0434\u043e\u043b\u044f \u043c\u043e\u043b\u0435\u043a\u0443\u043b, \u043f\u0440\u043e\u0445\u043e\u0434\u044f\u0449\u0438\u0445 compound-\u043f\u0440\u043e\u0444\u0438\u043b\u044c (QED \u2265 0.6; p-logP \u0432 drug-like \u043e\u043a\u043d\u0435 [1; 4] \u2014 \u0433\u0440\u0430\u043d\u0438\u0446\u044b \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043f\u043e \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0443 \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430; affinity \u2265 \u043f\u043e\u0440\u043e\u0433\u0430 \u00abactives\u00bb).\n- **Secondary:** \u043c\u0435\u0434\u0438\u0430\u043d\u044b, \u0394medians \u0441 \u0431\u0443\u0442\u0441\u0442\u0440\u044d\u043f-CI.\n\n### 5.2 \u0413\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0438 (H2) \u2014 \u043c\u043d\u043e\u0433\u043e\u0443\u0440\u043e\u0432\u043d\u0435\u0432\u0430\u044f \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u21164), \u043e\u0442\u0447\u0451\u0442 \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u043c\u0443 \u0443\u0440\u043e\u0432\u043d\u044e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\n- **L-a. \u0421\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0447\u0435\u0441\u043a\u0438\u0439:** \u0434\u043e\u043b\u044f \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0445 SMILES (parse-failure RDKit); \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u2014 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435, \u043d\u043e \u0441 unsanitizable \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043e\u0439 (valence errors).\n- **L-b. \u0410\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u043d\u0430\u044f \u0445\u0438\u043c\u0438\u044f:** \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435 \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044b \u0441 \u043d\u0435\u0436\u0435\u043b\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u043c\u0438/\u0440\u0435\u0430\u043a\u0442\u0438\u0432\u043d\u044b\u043c\u0438 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u0430\u043c\u0438 \u2014 PAINS, Brenk, RDKit filter catalog, \u043f\u043b\u044e\u0441 \u0447\u0435\u043a\u0435\u0440\u044b \u043d\u0430 \u043f\u0435\u0440\u043e\u043a\u0441\u0438\u0434\u044b, \u0438\u043c\u0438\u043d\u044b, \u043d\u0435\u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435 \u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438, \u00ab\u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044b-\u043c\u043e\u0441\u0442\u044b\u00bb \u0447\u0435\u0440\u0435\u0437 \u043e\u0434\u0438\u043d \u0430\u0442\u043e\u043c.\n- **L-c. \u0421\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u044b\u0435 \u0432\u044b\u0431\u0440\u043e\u0441\u044b \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430:** \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044b \u0432 \u0445\u0432\u043e\u0441\u0442\u0435 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 drug-like \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430 (\u00a76) \u2014 \u043c\u043d\u043e\u0433\u043e\u043c\u0435\u0440\u043d\u043e\u0435 \u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u043e (MW, logP, TPSA, HBD/HBA, rotB, ring counts, Fsp3) \u0441 isolation forest \u0438\u043b\u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u043e\u043c \u00ab\u0432\u043d\u0435 99-\u0433\u043e \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044f \u2265 2 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432 \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e\u00bb.\n- **L-c\u2032 (\u043d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e):** \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b, \u043d\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u044e\u0449\u0438\u0435 \u043d\u0438 \u0441 \u043e\u0434\u043d\u0438\u043c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c \u043b\u0438\u0433\u0430\u043d\u0434\u043e\u043c \u0438 \u043d\u0435 \u043f\u043e\u043a\u0440\u044b\u0442\u044b\u0435 \u043d\u0438 \u043e\u0434\u043d\u0438\u043c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043d\u044b\u043c \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u043e\u043c \u2014 \u043d\u0430\u0438\u0431\u043e\u043b\u0435\u0435 \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u044b\u0435 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u044b \u0432 \u00ab\u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0438\u00bb.\n\n### 5.3 \u0420\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u0435 \u0438 \u043f\u0435\u0440\u0435\u043a\u043e\u0441 \u043a \u0434\u043b\u0438\u043d\u043d\u044b\u043c \u0446\u0435\u043f\u044f\u043c (H3)\n- **Ultra-long carbon chains (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u21165, \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f):** \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044b \u2014 \u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f \u0430\u043b\u0438\u0444\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0446\u0435\u043f\u044c (sp3-\u0443\u0433\u043b\u0435\u0440\u043e\u0434\u044b, \u0441\u0432\u044f\u0437\u0438 C\u2013C, \u0431\u0435\u0437 \u0433\u0435\u0442\u0435\u0440\u043e\u0430\u0442\u043e\u043c\u043e\u0432 \u0438 \u0446\u0438\u043a\u043b\u043e\u0432 \u0432\u0434\u043e\u043b\u044c \u0446\u0435\u043f\u0438). \u041f\u043e\u0440\u043e\u0433: **N = 99-\u0439 \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044c \u044d\u0442\u043e\u0433\u043e \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u043d\u0430 drug-like \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0435** (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e ~8\u201312 C; \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430). \u041c\u0435\u0442\u0440\u0438\u043a\u0438: (i) \u0434\u043e\u043b\u044f \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u0441 \u0446\u0435\u043f\u044c\u044e \u2265 N (over-representation); (ii) \u043f\u043e\u043b\u043d\u044b\u0435 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0434\u043b\u0438\u043d \u043f\u043e \u043f\u043b\u0435\u0447\u0430\u043c \u0441 KS-\u0442\u0435\u0441\u0442\u043e\u043c \u0438 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435\u043c tail-mass. \u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 \u043f\u043e\u0440\u043e\u0433\u0430: data-driven \u043e\u0442 \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430 \u2014 \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432 \u043a \u0441\u043f\u043e\u0440\u0443 \u043e \u00ab\u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e\u0439\u00bb \u0433\u0440\u0430\u043d\u0438\u0446\u0435.\n- **Scaffold-\u0440\u0430\u0437\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u0438\u0435:** \u0447\u0438\u0441\u043b\u043e \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 Bemis\u2013Murcko scaffolds; unique scaffolds / valid molecules; top-10 scaffold coverage (\u0440\u0430\u043d\u043d\u0438\u0439 \u0434\u0435\u0442\u0435\u043a\u0442\u043e\u0440 \u043a\u043e\u043b\u043b\u0430\u043f\u0441\u0430).\n- **Internal diversity:** \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u0438 \u043c\u0435\u0434\u0438\u0430\u043d\u0430 pairwise Tanimoto (Morgan fp, r=2, 2048 bit) \u043d\u0430 \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435 (\u2264 5 000 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0439), + Shannon entropy \u043f\u043e \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0430\u043c (Butina, Tanimoto cutoff 0.4).\n- **\u0423\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c:** \u0434\u043e\u043b\u044f \u0443\u043d\u0438\u043a\u0430\u043b\u044c\u043d\u044b\u0445 canonical SMILES.\n\n### 5.4 \u0412\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435 \u0441 real-world \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435\u043c (H4)\nMMD (\u0438\u043b\u0438 Frechet-\u043f\u043e\u0434\u043e\u0431\u043d\u0430\u044f \u0434\u0438\u0441\u0442\u0430\u043d\u0446\u0438\u044f) \u043f\u043e \u0432\u0435\u043a\u0442\u043e\u0440\u0443 [MW, logP, TPSA, QED, HBD, HBA, rotB, rings, Fsp3] \u043c\u0435\u0436\u0434\u0443 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0435\u0439 \u0438 drug-like \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043e\u043c; \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 A-\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441 vs B-\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441.\n\n---\n\n## 6. \u0420\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u043d\u043e\u0435 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435\n\nDrug-like subset ChEMBL/ZINC: MW 150\u2013600, \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043d\u043d\u044b\u0435 \u0430\u0442\u043e\u043c\u044b C/N/O/S/F/Cl/Br/I, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430\u044f \u043f\u0440\u0435\u0434\u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0430 \u0441 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f\u043c\u0438. \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0434\u043b\u044f: \u043f\u043e\u0440\u043e\u0433\u0430 ultra-long chain (\u00a75.3), compound-\u043f\u0440\u043e\u0444\u0438\u043b\u044f (\u00a75.1), MMD-\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430 (\u00a75.4), L-c-\u0432\u044b\u0431\u0440\u043e\u0441\u043e\u0432 (\u00a75.2). \u0420\u0430\u0437\u043c\u0435\u0440 \u2265 50 000 \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0439. \u0412\u0435\u0440\u0441\u0438\u044f \u0431\u0430\u0437\u044b \u0438 \u0444\u0438\u043b\u044c\u0442\u0440\u044b \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430.\n\n---\n\n## 7. Binding affinity (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u21163)\n\n- **\u041e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u2014 \u043e\u0431\u0443\u0447\u0435\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u043e\u0440-\u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442:** GBM/RF \u0438\u043b\u0438 \u043f\u0440\u0435\u0434\u043e\u0431\u0443\u0447\u0435\u043d\u043d\u0430\u044f graph/sequence-\u043c\u043e\u0434\u0435\u043b\u044c, \u043d\u0430\u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043d\u0430 PDBbind-\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0445 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u0438/\u0438\u043b\u0438 ChEMBL actives/inactives \u0442\u0430\u0440\u0433\u0435\u0442\u0430 (fallback \u2014 \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f actives vs random drug-like, \u0435\u0441\u043b\u0438 Ki \u0440\u0430\u0437\u043d\u043e\u0440\u043e\u0434\u043d\u044b). \u0412\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430: hold-out (20 %) ROC-AUC/RMSE; \u043f\u043e\u0440\u043e\u0433 \u043f\u0440\u0438\u0433\u043e\u0434\u043d\u043e\u0441\u0442\u0438 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, AUC \u2265 0.80); \u043f\u0440\u0438 \u043f\u0440\u043e\u0432\u0430\u043b\u0435 \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0437\u0430\u043f\u0430\u0441\u043d\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 (fast docking \u043a\u0430\u043a \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439).\n- **\u0412\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u2014 fast docking (AutoDock Vina, CPU):** \u043d\u0430 \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435 (~500 \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u043d\u0430 \u043f\u043b\u0435\u0447\u043e: top-100 / random-200 / bottom-200 \u043f\u043e \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0443) \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u0435 \u0440\u0430\u043d\u0436\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043c\u0435\u0436\u0434\u0443 \u043f\u043b\u0435\u0447\u0430\u043c\u0438 \u043f\u043e docked score. \u0414\u043e\u043f\u0443\u0441\u043a \u0437\u0430\u0440\u0430\u043d\u0435\u0435: Spearman \u03c1(\u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442, docked score) \u2265 0.5 \u043d\u0430 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435; \u0438\u043d\u0430\u0447\u0435 \u0432\u044b\u0432\u043e\u0434 \u043f\u043e affinity \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442-\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0439.\n- **Assumption:** affinity \u0432\u043e \u0432\u0441\u0435\u0445 \u0432\u044b\u0432\u043e\u0434\u0430\u0445 \u2014 \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u043d\u0430\u044f \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0430; \u00ab\u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0430\u044f\u00bb \u0431\u0438\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u0442\u0441\u044f (\u043f\u0440\u043e\u043f\u0438\u0441\u0430\u043d\u043e \u0432 limitations).\n\n---\n\n## 8. \u0411\u044e\u0434\u0436\u0435\u0442 \u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c (\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u21163)\n\n**\u041c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u043e \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u0439 \u043e\u0431\u044a\u0451\u043c (\u043d\u0430 \u043f\u043b\u0435\u0447\u043e):** 10 000 \u0441\u0433\u0435\u043d\u0435\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 SMILES (\u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e ~8 000 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0445 \u043f\u0440\u0438 \u0442\u0438\u043f\u0438\u0447\u043d\u043e\u0439 validity 70\u201395 %).\n- *Primary property metric (\u0434\u043e\u043b\u044f pass \u043f\u0440\u043e\u0444\u0438\u043b\u044f):* \u0434\u0435\u0442\u0435\u043a\u0442 \u0394=10 \u043f.\u043f. (15 %\u219225 %) \u043f\u0440\u0438 \u03b1=0.05, power 0.80 \u2192 ~370/\u043f\u043b\u0435\u0447\u043e; \u043a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u0394=5 \u043f.\u043f. \u2192 ~1 400. \u0417\u0430\u043f\u0430\u0441 \u043d\u0430 \u043d\u0435\u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435 SMILES \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0441\u044f 10k \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0439.\n- *Hallucination rate:* \u0394=5 \u043f.\u043f. \u2192 ~700 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0445 \u043d\u0430 \u043f\u043b\u0435\u0447\u043e.\n- *Diversity-\u043c\u0435\u0442\u0440\u0438\u043a\u0438:* \u0431\u0443\u0442\u0441\u0442\u0440\u044d\u043f (10 000 \u0440\u0435\u0441\u043f\u044d\u043c\u043f\u043b\u043e\u0432) CI \u043d\u0430 internal diversity \u0438 scaffold-\u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044f\u0445 \u0441\u0443\u0436\u0430\u044e\u0442\u0441\u044f \u0434\u043e \u00b10.01\u20130.02 \u043f\u0440\u0438 n \u2265 3 000\u20135 000 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0445.\n- *\u0418\u0442\u043e\u0433:* 10k/\u043f\u043b\u0435\u0447\u043e \u2014 \u043c\u0438\u043d\u0438\u043c\u0443\u043c, \u0434\u0430\u044e\u0449\u0438\u0439 powered-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 H1, H2 \u0438 \u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c\u044b\u0435 CI \u043f\u043e H3/H4.\n\n**\u0420\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u043d\u044b\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442:** 50 000\u2013100 000 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0439 \u043d\u0430 \u043f\u043b\u0435\u0447\u043e \u2014 \u0443\u0437\u043a\u0438\u0435 CI \u043d\u0430 tail-metrics (\u0434\u043e\u043b\u044f ultra-long chains \u2014 \u0440\u0435\u0434\u043a\u043e\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u0435; \u0434\u043b\u044f \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0439 tail-mass \u043d\u0443\u0436\u043d\u043e \u2265 50k), docking \u043f\u043e 1 000 \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u043d\u0430 \u043f\u043b\u0435\u0447\u043e, powered-\u0430\u0431\u043b\u044f\u0446\u0438\u0438 C/D.\n\n**\u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c:** \u043f\u0440\u0438 5k/\u043f\u043b\u0435\u0447\u043e \u2014 H1/H2 powered, H3/H4 exploratory \u0441 \u0448\u0438\u0440\u043e\u043a\u0438\u043c\u0438 CI; \u043f\u0440\u0438 100k \u2014 \u0432\u0441\u0435 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b powered + \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u0430\u044f \u0430\u0431\u043b\u044f\u0446\u0438\u044f.\n\n---\n\n## 9. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0438 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430\n\n1. **\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437:** \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u2014 \u043e\u0446\u0435\u043d\u043a\u0438 \u0432 A \u0438 B, \u0394 \u0441 \u0431\u0443\u0442\u0441\u0442\u0440\u044d\u043f-CI (10 000 \u0440\u0435\u0441\u043f\u044d\u043c\u043f\u043b\u043e\u0432), permutation-\u0442\u0435\u0441\u0442 (10 000 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u043e\u0432\u043e\u043a) \u0438\u043b\u0438 paired-\u0442\u0435\u0441\u0442 (Wilcoxon signed-rank) \u0442\u0430\u043c, \u0433\u0434\u0435 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0435\u043d pairing \u043f\u043e seed-\u0446\u0435\u043f\u043e\u0447\u043a\u0435.\n2. **\u041f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 \u043d\u0430 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c:** Benjamini\u2013Hochberg (FDR q=0.05) **\u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u0430\u0436\u0434\u043e\u0439 \u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0441\u0435\u043c\u044c\u0438** (properties / hallucinations / diversity / alignment); \u043c\u0435\u0436\u0441\u0435\u043c\u0435\u0439\u043d\u043e \u043d\u0435 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u0443\u0435\u043c, \u0442.\u043a. \u0441\u0435\u043c\u044c\u0438 \u043e\u0442\u0432\u0435\u0447\u0430\u044e\u0442 \u043d\u0430 \u0440\u0430\u0437\u043d\u044b\u0435 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b; \u043a\u0430\u0436\u0434\u0430\u044f \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043a\u043e\u043d\u044a\u044e\u043d\u043a\u0446\u0438\u044f \u0441\u0432\u043e\u0438\u0445 \u043c\u0435\u0442\u0440\u0438\u043a \u0441 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435\u043c \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u0438 \u0437\u043d\u0430\u043a\u043e\u0432.\n3. **Effect sizes:** Cohen's h \u0434\u043b\u044f \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u0439, Cliff's delta \u0434\u043b\u044f \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0439 \u2014 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b: \u043f\u0440\u0438 n=10k \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u043e\u0447\u0442\u0438 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u0434\u0430\u0436\u0435 \u0434\u043b\u044f \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0439; \u0432\u044b\u0432\u043e\u0434\u044b \u2014 \u043f\u043e \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0435 \u044d\u0444\u0444\u0435\u043a\u0442\u0430, \u043d\u0435 \u043f\u043e p-value.\n4. **Sensitivity-\u0430\u043d\u0430\u043b\u0438\u0437\u044b:** (i) \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 1 % \u043a\u0440\u0430\u0439\u043d\u0438\u0445 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0439; (ii) \u043f\u043e\u0440\u043e\u0433 ultra-long chain \u043f\u043e 98-\u043c\u0443 \u0438 95-\u043c\u0443 \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044f\u043c \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u0432\u044b\u0432\u043e\u0434 \u043d\u0435 \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442 \u0432\u044b\u0431\u043e\u0440\u0430 N; (iii) \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u043e\u0435 \u043e\u043a\u043d\u043e p-logP \u0432 primary metric.\n5. **\u041f\u0440\u0435\u0434\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044f:** \u043f\u043e\u0440\u043e\u0433\u0438, \u0432\u0435\u0440\u0441\u0438\u0438 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u043e\u0432, seed-\u0441\u043f\u0438\u0441\u043a\u0438, dedup-\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438; post-hoc \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043c\u0430\u0440\u043a\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a exploratory.\n\n---\n\n## 10. Feasibility (\u0435\u0441\u043b\u0438 \u0431\u044b \u0434\u0438\u0437\u0430\u0439\u043d \u0438\u0441\u043f\u043e\u043b\u043d\u044f\u043b\u0441\u044f)\n\n- **CPU-only:** RDKit (p-logP, QED, \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043d\u044b\u0435 \u0444\u0438\u043b\u044c\u0442\u0440\u044b, scaffold-\u0430\u043d\u0430\u043b\u0438\u0437, \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u044b), Butina-\u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0438\u0437\u0430\u0446\u0438\u044f, isolation forest, \u0431\u0443\u0442\u0441\u0442\u0440\u044d\u043f/\u043f\u0435\u0440\u043c\u0443\u0442\u0430\u0446\u0438\u0438, Vina \u043d\u0430 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435, \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u0435 GBM/RF-\u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 \u043d\u0430 ~1\u20135k \u0441\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0439.\n- **\u0423\u0437\u043a\u0438\u0435 \u043c\u0435\u0441\u0442\u0430:** (i) \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0435 \u043f\u0440\u0435\u0434\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0430 \u0432 design-only \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u2014 \u043f\u0440\u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0438 \u043d\u0443\u0436\u0435\u043d \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 (\u0438\u043b\u0438 CPU-\u0430\u043d\u0430\u043b\u043e\u0433\u0443 \u0441 \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442\u043e\u043c \u0431\u044e\u0434\u0436\u0435\u0442\u0430); (ii) docking 1 000 \u043c\u043e\u043b\u0435\u043a\u0443\u043b \u00d7 50 \u0440\u0430\u043a\u0443\u0440\u0441\u043e\u0432 \u2248 \u0447\u0430\u0441\u044b CPU \u2014 \u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c\u043e; (iii) MMD 10k\u00d710k \u2014 \u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c\u043e \u0441 linear-time \u043f\u0440\u0438\u0431\u043b\u0438\u0436\u0435\u043d\u0438\u0435\u043c.\n- **\u0412\u0435\u0440\u0434\u0438\u043a\u0442:** \u044f\u0434\u0440\u043e A/B + \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u0438\u043c\u043e \u043d\u0430 CPU \u0432 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u0445 \u0434\u0435\u0441\u044f\u0442\u043a\u043e\u0432 \u0447\u0430\u0441\u043e\u0432; extended \u2014 \u0435\u0434\u0438\u043d\u0438\u0446\u044b CPU-\u0434\u043d\u0435\u0439. GPU \u043d\u0443\u0436\u0435\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u043d\u0435\u0439\u0440\u043e\u0441\u0435\u0442\u0435\u0432\u043e\u0433\u043e \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0438\u043b\u0438 \u043d\u0435\u0439\u0440\u043e\u0441\u0435\u0442\u0435\u0432\u043e\u0433\u043e \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 affinity.\n\n---\n\n## 11. Assumptions\n\n1. Feedback-\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u043c\u0435\u0442\u043e\u0434-\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u043d: \u043b\u044e\u0431\u0430\u044f \u043f\u0435\u0442\u043b\u044f, \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0449\u0430\u044f p-logP/QED/affinity (conditioning / reranking / iterative refinement), \u2014 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u0430\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f.\n2. Binding affinity \u2014 \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442: \u043e\u0431\u0443\u0447\u0435\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u043e\u0440 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439, fast docking \u2014 \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438; \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0430\u044f \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u043d\u0435 \u0438\u0437\u043c\u0435\u0440\u044f\u0435\u0442\u0441\u044f.\n3. \u0411\u0430\u0437\u043e\u0432\u044b\u0439 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u2014 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u043b\u044c\u043d\u0430\u044f SMILES-\u043c\u043e\u0434\u0435\u043b\u044c; \u0434\u0438\u0437\u0430\u0439\u043d \u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0435\u043d \u043a \u0435\u0451 \u0442\u0438\u043f\u0443.\n4. \u0420\u0435\u0444\u0435\u0440\u0435\u043d\u0441 real-world \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u2014 drug-like subset ChEMBL/ZINC; \u00ab\u0432\u044b\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u043d\u0438\u0435\u00bb \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u0447\u0435\u0440\u0435\u0437 MMD \u043f\u043e \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043d\u043e\u043c\u0443 \u0432\u0435\u043a\u0442\u043e\u0440\u0443.\n5. \u041e\u0434\u0438\u043d \u0442\u0430\u0440\u0433\u0435\u0442 (\u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0435: EGFR \u043f\u043e \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f\u043c \u00a73); \u0432\u044b\u0432\u043e\u0434\u044b \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u0441\u0435\u0442\u0430\u043f\u0430.\n6. \u041f\u043e\u0440\u043e\u0433 ultra-long chain \u2014 data-driven (99-\u0439 \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044c drug-like \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430), \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430.\n7. \u0414\u0432\u0443\u0445\u043f\u043b\u0435\u0447\u0435\u0432\u043e\u0439 \u0434\u0438\u0437\u0430\u0439\u043d \u2014 \u044f\u0434\u0440\u043e; \u0430\u0431\u043b\u044f\u0446\u0438\u044f p-logP/QED-only vs +affinity \u2014 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u043c\u043e\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435, \u043d\u0435 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0435.\n\n## 12. Limitations\n\n- **\u041e\u0434\u043d\u0430 \u0442\u043e\u0447\u043a\u0430 \u0432\u044b\u0431\u043e\u0440\u0430 \u0442\u0430\u0440\u0433\u0435\u0442\u0430:** \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u043d\u0430 \u043e\u0434\u043d\u043e\u0439 \u043a\u0438\u043d\u0430\u0437\u0435 \u043d\u0435 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043d\u0430 \u0434\u0440\u0443\u0433\u0438\u0435 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430; \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e \u0441\u043c\u044f\u0433\u0447\u0430\u0435\u0442\u0441\u044f hold-out-\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u043e\u0439 \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 (\u00a77), \u043d\u043e \u043d\u0435 \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442 \u043c\u0443\u043b\u044c\u0442\u0438-\u0442\u0430\u0440\u0433\u0435\u0442\u043d\u044b\u0439 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442.\n- **\u0421\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u043d\u0430\u044f \u043f\u0440\u0438\u0440\u043e\u0434\u0430 affinity:** \u00ab\u0443\u043b\u0443\u0447\u0448\u0430\u0435\u0442 affinity\u00bb = \u00ab\u0443\u043b\u0443\u0447\u0448\u0430\u0435\u0442 \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u043d\u0443\u044e/\u0434\u043e\u043a\u0438\u043d\u0433-\u043e\u0446\u0435\u043d\u043a\u0443\u00bb; \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u044c \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0430 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e\u043c \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 \u0438 \u0435\u0433\u043e \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0438 \u0441 docked score \u043d\u0430 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435.\n- **\u00ab\u0413\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u044f\u00bb \u2014 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0435\u0440\u043c\u0438\u043d:** \u0442\u0440\u0438 \u0443\u0440\u043e\u0432\u043d\u044f (\u00a75.2) \u043b\u043e\u0432\u044f\u0442 \u0440\u0430\u0437\u043d\u044b\u0435 \u0440\u0435\u0436\u0438\u043c\u044b \u043e\u0442\u043a\u0430\u0437\u0430, \u043d\u043e \u043d\u0435 \u0438\u0441\u0447\u0435\u0440\u043f\u044b\u0432\u0430\u044e\u0442 \u00ab\u0431\u0438\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438 \u0431\u0435\u0441\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u044b\u0435, \u043d\u043e \u0445\u0438\u043c\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u0435\u00bb \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b; L-c\u2032 \u2014 \u044d\u0432\u0440\u0438\u0441\u0442\u0438\u043a\u0430.\n- **Equal-budget \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0437\u0430\u0449\u0438\u0449\u0430\u0435\u0442 \u043e\u0442 \u00ab\u0431\u043e\u043b\u044c\u0448\u0435 \u0441\u044d\u043c\u043f\u043b\u043e\u0432 = \u043b\u0443\u0447\u0448\u0435\u00bb, \u043d\u043e \u043d\u0435 \u043e\u0442 \u0442\u043e\u0433\u043e, \u0447\u0442\u043e feedback-\u043f\u0435\u0442\u043b\u044f \u043f\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044e \u0442\u0440\u0430\u0442\u0438\u0442 \u0431\u043e\u043b\u044c\u0448\u0435 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 \u043d\u0430 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u0430.** \u0415\u0441\u043b\u0438 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u043d compute-matched, \u0430 \u043d\u0435 sample-matched \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c, \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0440\u0435\u0442\u0438\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442: baseline \u0441 \u0431\u044e\u0434\u0436\u0435\u0442\u043e\u043c \u00ab\u0432\u0440\u0435\u043c\u044f baseline + \u0432\u0440\u0435\u043c\u044f \u043f\u0435\u0442\u043b\u0438\u00bb.\n- **Design-only:** \u043d\u0438\u043a\u0430\u043a\u0438\u0445 \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u0432; \u043f\u043e\u0440\u043e\u0433\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u2014 \u0440\u0430\u0441\u0447\u0451\u0442\u043d\u044b\u0435 \u0438 \u0442\u0440\u0435\u0431\u0443\u044e\u0442 \u043f\u0435\u0440\u0435\u0441\u0447\u0451\u0442\u0430 \u043d\u0430 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u043f\u0440\u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0438.\n- **\u041d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0439 \u043d\u0430 \u0441\u0442\u0430\u0434\u0438\u0438 \u0434\u0438\u0437\u0430\u0439\u043d\u0430 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440** \u043c\u043e\u0436\u0435\u0442 \u0438\u043c\u0435\u0442\u044c \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u044e\u044e \u0432\u0430\u0440\u0438\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c, \u043d\u0435 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u043f\u043e\u043a\u0440\u044b\u0432\u0430\u0435\u043c\u0443\u044e seeds; \u043f\u0440\u0438 extended-\u0431\u044e\u0434\u0436\u0435\u0442\u0435 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u0442\u0441\u044f \u2265 3 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0445 seed-\u043d\u0430\u0431\u043e\u0440\u0430 \u043d\u0430 \u043f\u043b\u0435\u0447\u043e.\n\n---\n\n*\u0414\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u2014 \u0434\u0438\u0437\u0430\u0439\u043d. \u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u0441\u044f; \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044e\u0442\u0441\u044f.*", "evidence": "\u0420\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0439: /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json, \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u044f\u0449\u0438\u0439 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u00abdesign-only; repositories and compute are not required\u00bb (\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043e find/ls \u043d\u0430 \u0433\u043b\u0443\u0431\u0438\u043d\u0443 3). \u0414\u0430\u0442\u0430\u0441\u0435\u0442\u044b: [] \u0432 environment metadata; \u0444\u0430\u0439\u043b track.md \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442. \u0414\u0438\u0437\u0430\u0439\u043d \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d \u043d\u0430 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0445 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0445 \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0430\u0445 (RDKit \u0434\u043b\u044f p-logP/QED/\u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043d\u044b\u0445 \u0444\u0438\u043b\u044c\u0442\u0440\u043e\u0432/scaffold-\u0430\u043d\u0430\u043b\u0438\u0437\u0430; ChEMBL/ZINC \u043a\u0430\u043a \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441 \u0438 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043b\u0438\u0433\u0430\u043d\u0434\u043e\u0432 \u0442\u0430\u0440\u0433\u0435\u0442\u0430; PDBbind/ChEMBL \u0434\u043b\u044f \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 affinity; AutoDock Vina \u043a\u0430\u043a \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f), \u0447\u0442\u043e \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f\u043c \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u0438 \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f\u043c \u0432\u044b\u0431\u043e\u0440\u0430 \u0442\u0430\u0440\u0433\u0435\u0442\u0430 \u00a73. \u041e\u0446\u0435\u043d\u043a\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u2014 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435 \u0444\u043e\u0440\u043c\u0443\u043b\u044b \u0434\u0432\u0443\u0445\u0432\u044b\u0431\u043e\u0440\u043e\u0447\u043d\u043e\u0433\u043e z-\u0442\u0435\u0441\u0442\u0430 \u0434\u043b\u044f \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u0439 (\u03b1=0.05, power=0.80): \u0394=10 \u043f.\u043f. \u2192 n\u2248370; \u0394=5 \u043f.\u043f. \u2192 n\u22481 400 \u043d\u0430 \u043f\u043b\u0435\u0447\u043e; \u0431\u0443\u0442\u0441\u0442\u0440\u044d\u043f-\u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u044c diversity-\u043c\u0435\u0442\u0440\u0438\u043a \u043e\u0446\u0435\u043d\u0435\u043d\u0430 \u043a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u043e (n\u22653\u20135k). \u0412\u0441\u0435 \u043f\u043e\u0440\u043e\u0433\u0438 (N \u0434\u043b\u044f ultra-long chain, \u043e\u043a\u043d\u0430 p-logP, \u0434\u043e\u043f\u0443\u0441\u043a Spearman \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442-vs-docking) \u0432\u044b\u043d\u0435\u0441\u0435\u043d\u044b \u0432 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044e \u00ab\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u00bb \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u0443\u0435\u0442\u0441\u044f \u0441 preregistration-\u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u0435\u043c \u00a79. \u0412\u0441\u0435 \u0448\u0435\u0441\u0442\u044c \u0440\u0435\u0448\u0435\u043d\u0438\u0439 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f \u0438\u043d\u043a\u043e\u0440\u043f\u043e\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u044b: \u0442\u0430\u0440\u0433\u0435\u0442 \u043f\u043e \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f\u043c (\u00a73), method-agnostic feedback (\u00a74), \u0431\u044e\u0434\u0436\u0435\u0442 \u0441 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c\u044e + \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442/\u0434\u043e\u043a\u0438\u043d\u0433-\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u044f (\u00a77\u20138), \u0442\u0440\u0451\u0445\u0443\u0440\u043e\u0432\u043d\u0435\u0432\u0430\u044f \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u044f (\u00a75.2), data-driven \u043f\u043e\u0440\u043e\u0433 \u0446\u0435\u043f\u0435\u0439 (\u00a75.3), \u0430\u0431\u043b\u044f\u0446\u0438\u044f \u043a\u0430\u043a \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435 (\u00a72, \u00a78).", "assumptions": ["Feedback-\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u043c\u0435\u0442\u043e\u0434-\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u043d: \u043b\u044e\u0431\u0430\u044f \u043f\u0435\u0442\u043b\u044f, \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u044e\u0449\u0430\u044f p-logP/QED/binding affinity \u0432 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044e (conditioning/reranking/iterative refinement), \u2014 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u0430\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f; \u0432\u044b\u0432\u043e\u0434 \u043d\u0435 \u043f\u0440\u0438\u0432\u044f\u0437\u0430\u043d \u043a \u043e\u0434\u043d\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0435", "Binding affinity \u2014 \u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442: \u043e\u0431\u0443\u0447\u0435\u043d\u043d\u044b\u0439 \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u043e\u0440 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439, fast docking (Vina) \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438", "\u0411\u0430\u0437\u043e\u0432\u044b\u0439 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u2014 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u043b\u044c\u043d\u0430\u044f SMILES-\u043c\u043e\u0434\u0435\u043b\u044c; \u0434\u0438\u0437\u0430\u0439\u043d \u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0435\u043d \u043a \u0435\u0451 \u0442\u0438\u043f\u0443", "\u0420\u0435\u0444\u0435\u0440\u0435\u043d\u0441 real-world \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u2014 drug-like subset ChEMBL/ZINC; alignment \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u043e\u0432\u0430\u043d \u0447\u0435\u0440\u0435\u0437 MMD \u043f\u043e \u0432\u0435\u043a\u0442\u043e\u0440\u0443 \u043c\u043e\u043b\u0435\u043a\u0443\u043b\u044f\u0440\u043d\u044b\u0445 \u0434\u0435\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0440\u043e\u0432", "\u041e\u0434\u0438\u043d \u0442\u0430\u0440\u0433\u0435\u0442 (\u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d EGFR, PDB 1M17, \u043f\u043e \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044f\u043c \u00a73); \u0432\u044b\u0432\u043e\u0434\u044b \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b \u0434\u043b\u044f \u044d\u0442\u043e\u0433\u043e \u0441\u0435\u0442\u0430\u043f\u0430", "\u041f\u043e\u0440\u043e\u0433 ultra-long carbon chain \u2014 data-driven: 99-\u0439 \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044c \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u043e\u0439 \u0430\u043b\u0438\u0444\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0446\u0435\u043f\u0438 \u043d\u0430 drug-like \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0435", "\u0410\u0431\u043b\u044f\u0446\u0438\u044f (feedback p-logP/QED-only vs +affinity) \u2014 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0443\u0435\u043c\u043e\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435, \u043d\u0435 \u044f\u0434\u0440\u043e \u0434\u0438\u0437\u0430\u0439\u043d\u0430"], "uncertainties": ["\u041a\u043e\u043d\u043a\u0440\u0435\u0442\u043d\u0430\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f feedback-\u043f\u0435\u0442\u043b\u0438 (reranking vs conditioning vs iterative refinement) \u0438 \u0447\u0438\u0441\u043b\u043e \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0439 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430; \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 A/B \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043a \u044d\u0442\u043e\u043c\u0443 \u0432\u044b\u0431\u043e\u0440\u0443", "\u0424\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e affinity-\u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u0430 \u043d\u0430 \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u043c \u0442\u0430\u0440\u0433\u0435\u0442\u0435 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e \u0434\u043e \u0442\u0440\u0435\u043d\u0438\u0440\u043e\u0432\u043a\u0438 (\u043f\u043e\u0440\u043e\u0433 AUC \u2265 0.80 \u2014 \u0444\u0438\u043b\u044c\u0442\u0440 \u043f\u0440\u0438\u0433\u043e\u0434\u043d\u043e\u0441\u0442\u0438)", "\u0422\u043e\u0447\u043d\u043e\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u0435 N (99-\u0439 \u043f\u0435\u0440\u0446\u0435\u043d\u0442\u0438\u043b\u044c drug-like \u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u0430) \u0432\u044b\u0447\u0438\u0441\u043b\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0434\u0430\u043d\u043d\u044b\u0445; \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u044b\u0439 \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d ~8\u201312 \u0430\u0442\u043e\u043c\u043e\u0432 C", "Compute-matched vs sample-matched \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c: \u0435\u0441\u043b\u0438 \u043f\u0435\u0442\u043b\u044f \u0434\u043e\u0440\u043e\u0436\u0435 \u043d\u0430 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u0430, sample-matched \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u043c \u2014 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f", "\u0414\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u044c \u0431\u0430\u0437\u043e\u0432\u043e\u0439 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u0438\u0432\u043d\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 \u043f\u0440\u0438 \u0440\u0435\u0430\u043b\u044c\u043d\u043e\u043c \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0438 (GPU/CPU) \u043c\u043e\u0436\u0435\u0442 \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u0431\u044e\u0434\u0436\u0435\u0442 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438", "\u041e\u0431\u043e\u0431\u0449\u0430\u0435\u043c\u043e\u0441\u0442\u044c \u0432\u044b\u0432\u043e\u0434\u0430 \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u044b \u043e\u0434\u043d\u043e\u0433\u043e \u043a\u0438\u043d\u0430\u0437\u043d\u043e\u0433\u043e \u0442\u0430\u0440\u0433\u0435\u0442\u0430 \u044d\u0442\u0438\u043c \u0434\u0438\u0437\u0430\u0439\u043d\u043e\u043c \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f"]}", "kind": "ActionEvent"}
